export interface DiscountPolicy {
  applyDiscount(subtotal: number): number;
}

export class PercentageDiscountPolicy implements DiscountPolicy {
  constructor(readonly percentage: number) {
    if (percentage < 0 || percentage > 100) throw new Error("Invalid percentage");
  }
  applyDiscount(subtotal: number): number {
    return subtotal * (1 - this.percentage / 100);
  }
}

export class FlatDiscountPolicy implements DiscountPolicy {
  constructor(readonly amount: number) {
    if (amount < 0) throw new Error("Invalid amount");
  }
  applyDiscount(subtotal: number): number {
    return Math.max(0, subtotal - this.amount);
  }
}

import { FlatDiscountPolicy, PercentageDiscountPolicy } from "./src/policy.ts";

const pct = new PercentageDiscountPolicy(10);
console.log("10% off £100 ->", pct.applyDiscount(100));  // 90

const flat = new FlatDiscountPolicy(15);
console.log("£15 off £100 ->", flat.applyDiscount(100)); // 85
console.log("£15 off £10  ->", flat.applyDiscount(10));  // 0 (floor at 0)
